INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(401, 'Genesis 17:7', 'Genesis', 17, 7, '&nbsp;زما به تا او ستا د اولاد سره دا لوظ وى، دا به په راتلونکو نسلونو کښې يو نۀ ختمېدونکے لوظ وى. زۀ به ستا او ستا د اولاد خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(402, 'Genesis 17:8', 'Genesis', 17, 8, '&nbsp;زۀ به تا او ستا اولاد له دا مُلک ورکوم په کوم کښې چې تۀ اوس مسافر يې. د کنعان ټول مُلک به همېشه دپاره ستا د اولاد وى او زۀ به د هغوئ خُدائ پاک يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(403, 'Genesis 17:9', 'Genesis', 17, 9, '&nbsp;خُدائ پاک اِبراهيم ته وفرمائيل، ”تۀ به زما سره دا لوظ پوره کوې، ستا او ستا د اولاد د راتلونکو نسلونو سره به دا لوظ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(404, 'Genesis 17:10', 'Genesis', 17, 10, '&nbsp;خو په دې شرط سره چې تۀ او ستا د اولاد هر يو نر به خامخا سنت کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(405, 'Genesis 17:13', 'Genesis', 17, 13, '&nbsp;هر يو به خامخا سنت کيږى، دا به په بدن يوه نښه وى چې پته لګى چې تا سره زما لوظ نۀ ختمېدونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(406, 'Genesis 17:14', 'Genesis', 17, 14, '&nbsp;خو چې کوم نر سنت شوے نۀ وى هغه به زما د خلقو نه بېل وى، ځکه چې هغۀ زما لوظ مات کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(407, 'Genesis 17:15', 'Genesis', 17, 15, '&nbsp;خُدائ پاک اِبراهيم ته وفرمائيل، ”تۀ نور خپلې ښځې ته سارۍ مۀ وايه، د نن نه پس د هغې نوم ساره شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(408, 'Genesis 17:16', 'Genesis', 17, 16, '&nbsp;زۀ به هغې له برکت ورکړم او د هغې نه به ستا يو زوئ پېدا شى. زۀ به هغې له برکت ورکړم او هغه به د قومونو مور شى او د هغې په اولاد کښې به بادشاهان وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(409, 'Genesis 17:17', 'Genesis', 17, 17, '&nbsp;اِبراهيم تندے په زمکه ولګولو، سجده يې وکړه، خو اِبراهيم په خندا شو، چې کله هغۀ سوچ کولو، ”چې يو سړے د سلو کالو زوړ وى د هغۀ بچى پېدا کېدے شى څۀ؟ د ساره بچى پېدا کېدے شى چې د لس کم سلو کالو ده؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(410, 'Genesis 17:18', 'Genesis', 17, 18, '&nbsp;اِبراهيم خُدائ پاک ته وفرمائيل، ”کاش چې تۀ اِسمٰعيل زما وارث کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(411, 'Genesis 17:19', 'Genesis', 17, 19, '&nbsp;خو خُدائ پاک وفرمائيل چې، ”نه. ستا د خپلې ښځې ساره نه به يو زوئ پېدا شى او د هغۀ نوم اِسحاق کېږده. د هغۀ او د هغۀ د اولاد سره به همېشه دپاره زما لوظ وى. کوم چې يو نۀ ختمېدونکے لوظ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(412, 'Genesis 17:20', 'Genesis', 17, 20, '&nbsp;ما ستا د اِسمٰعيل دپاره سوال اورېدلے دے، نو هغۀ له به هم برکت ورکړم او هغۀ له به ډېر بچى او ډېر اولاد ورکړم. هغه به د دولسو بادشاهانو پلار وى او زۀ به د هغۀ د اولاد نه يو لوئ قوم جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(413, 'Genesis 17:21', 'Genesis', 17, 21, '&nbsp;خو زما به ستا د زوئ اِسحاق سره لوظ وى، چې هغه به تقريباً بل کال په دې ورځو کښې د ساره نه پېدا کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(414, 'Genesis 17:22', 'Genesis', 17, 22, '&nbsp;چې کله خُدائ پاک د اِبراهيم سره خبرې تر سره کړې، نو ترې نه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(415, 'Genesis 17:23', 'Genesis', 17, 23, '&nbsp;هم په هغه ورځ اِبراهيم اِسمٰعيل او په کور کښې چې څومره نران پېدا شوى وُو هغه ټول يې سنت کړل، سره د هغه نوکرانو چې د هغۀ په کور کښې پېدا شوى وُو او هغه يې هم سنت کړل چې د بل مُلک نه راوستلے شوى وُو لکه څنګه چې خُدائ پاک هغۀ ته فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(416, 'Genesis 17:24', 'Genesis', 17, 24, '&nbsp;اِبراهيم د يو کم سلو کالو وو چې هغه سنت شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(417, 'Genesis 17:25', 'Genesis', 17, 25, '&nbsp;او د هغۀ زوئ اِسمٰعيل د ديارلسو کالو وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(418, 'Genesis 17:26', 'Genesis', 17, 26, '&nbsp;دوئ دواړه په يوه ورځ سنت شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(419, 'Genesis 17:27', 'Genesis', 17, 27, '&nbsp;او ورسره د اِبراهيم ټول نوکران هم سنت شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(420, 'Genesis 18:1', 'Genesis', 18, 1, '&nbsp;مالِک خُدائ اِبراهيم ته د ممرې پاکو ونو سره راڅرګند شو. چې اِبراهيم د سرې غرمې په وخت د خېمې د دروازې په خولۀ کښې ناست وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(421, 'Genesis 18:2', 'Genesis', 18, 2, '&nbsp;هغۀ وکتل او څۀ ګورى چې هلته درې سړى ولاړ دى. هغوئ يې چې څنګه وليدل، هغۀ ستړى مشى له ورمنډه کړل. د عزت نه ورته ټيټ شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(422, 'Genesis 18:3', 'Genesis', 18, 3, '&nbsp;اِبراهيم وفرمائيل، ”صاحِبانو، کۀ تاسو ما د دې قابل ګڼئ، نو زما سره ايسار شئ چې زۀ ستاسو خِدمت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(423, 'Genesis 18:4', 'Genesis', 18, 4, '&nbsp;کۀ اجازت وى نو زۀ به ستاسو پښو وينځلو له لږې اوبۀ راوړم، تاسو د دې ونې لاندې دمه وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(424, 'Genesis 18:5', 'Genesis', 18, 5, '&nbsp;زۀ به تاسو له لږه روټۍ هم راوړم، نو تاسو به بيا ښۀ مزل وکړئ. دا زما دپاره د عزت خبره ده چې زما کور ته راغلئ، نو زۀ به ستاسو مېلمستيا کوم.“ هغوئ جواب ورکړو، ”ښۀ ده، چې څنګه ستا خوښه وى نو هغه شان وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(425, 'Genesis 18:6', 'Genesis', 18, 6, '&nbsp;اِبراهيم خېمې ته تېز لاړو او ساره ته يې وفرمائيل، ”زر شه. د ټولو نه د ښۀ اوړو بوجۍ راواخله او روټۍ ترې پخې کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(426, 'Genesis 18:7', 'Genesis', 18, 7, '&nbsp;بيا هغۀ د مال رَمې ته ورمنډه کړه او يو کچه او څورب سخے يې راونيوو او يو نوکر له يې ورکړو، چې هغه يې زر زر تيار کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(427, 'Genesis 18:8', 'Genesis', 18, 8, '&nbsp;هغۀ لږ ماستۀ، پئ او هغه پخه شوې غوښه هم راوړه او سړو ته يې هر څۀ کېښودل او چې کله هغوئ روټۍ خوړله نو د ونې لاندې ورته ولاړ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(428, 'Genesis 18:9', 'Genesis', 18, 9, '&nbsp;بيا هغوئ د هغۀ نه تپوس وکړو، ”ستا ښځه ساره چرته ده؟“ هغۀ جواب ورکړو، ”هغه دننه په خېمه کښې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(429, 'Genesis 18:10', 'Genesis', 18, 10, '&nbsp;يو مېلمه ووئيل، ”په راتلونکى کال کښې به زۀ واپس راشم او ستا د ښځې ساره به يو زوئ پېدا شوے وى.“ ساره د خېمې د دروازې شا ته دا خبرې اورېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(430, 'Genesis 18:11', 'Genesis', 18, 11, '&nbsp;اوس ګوره، اِبراهيم او ساره ډېر بوډاګان وُو. او ساره د ماشوم د پېدا کېدو نۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(431, 'Genesis 18:12', 'Genesis', 18, 12, '&nbsp;نو ساره د ځان سره وخندل او وې وئيل چې، ”اوس زۀ زَړه او کمزورې يم او خاوند مې هم بوډا دے، نو اوس په دې عُمر کښې به زۀ د هغۀ سره څملم څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(432, 'Genesis 18:13', 'Genesis', 18, 13, '&nbsp;نو مالِک خُدائ د اِبراهيم نه تپوس وکړو، ”ساره ولې وخندل او وې وئيل چې په دې عُمر کښې زما ماشوم پېدا کېدے شى څۀ ځکه چې زۀ ډېره بوډۍ يم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(433, 'Genesis 18:14', 'Genesis', 18, 14, '&nbsp;داسې څۀ شته چې د مالِک خُدائ دپاره مشکل وى؟ لکه چې څنګه ما ووئيل، په راتلونکى کال به زۀ واپس راځم او د ساره به يو زوئ پېدا شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(434, 'Genesis 18:15', 'Genesis', 18, 15, '&nbsp;نو ساره منکره شوه ځکه چې هغه يرېده. هغې ووئيل، ”ما خو نۀ دى خندلى.“ هغۀ جواب ورکړو، ”آو، تا وخندل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(435, 'Genesis 18:16', 'Genesis', 18, 16, '&nbsp;بيا هغه سړى روان شول او يو داسې ځائ ته لاړل چې د کوم ځائ نه يې سدوم ليدلے شو، نو اِبراهيم هغوئ ته په مخه ښه وئيلو دپاره ورسره لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(436, 'Genesis 18:17', 'Genesis', 18, 17, '&nbsp;نو مالِک خُدائ د ځان سره وفرمائيل، ”زۀ چې څۀ کول غواړم هغه به د اِبراهيم نه نۀ پټوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(437, 'Genesis 18:18', 'Genesis', 18, 18, '&nbsp;د هغۀ اولاد به يو لوئ طاقتور قوم وى او د هغۀ په ذريعه به زۀ ټولو قومونو له برکت ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(438, 'Genesis 18:19', 'Genesis', 18, 19, '&nbsp;ما هغه د دې دپاره غوره کړے دے چې هغه خپلو زامنو او اولاد ته دا نصيحت وکړى چې زما خبره منى او هغه څۀ کوى چې کوم صحيح او حق دى. کۀ دوئ داسې کوى، نو زۀ به هم د هغۀ دپاره هغه هر څۀ وکړم چې ما يې وعده کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(439, 'Genesis 18:20', 'Genesis', 18, 20, '&nbsp;بيا مالِک خُدائ اِبراهيم ته وفرمائيل، ”په سدوم او عموره باندې ډېر سخت اِلزامونه دى، دوئ ډېر بد عملونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(440, 'Genesis 18:21', 'Genesis', 18, 21, '&nbsp;زۀ به لاندې خامخا ځم چې دا پته ولګوم چې کوم اِلزامونه ما اورېدلى دى چې هغه رښتيا دى او کۀ نه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(441, 'Genesis 18:22', 'Genesis', 18, 22, '&nbsp;بيا هغه دوه سړى لاړل او د سدوم طرف ته روان شول، خو مالِک خُدائ د اِبراهيم سره ايسار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(442, 'Genesis 18:23', 'Genesis', 18, 23, '&nbsp;اِبراهيم مالِک خُدائ ته نزدې شو او تپوس يې ترې وکړو، ”تۀ په رښتيا د بدعملو سره صادقان هم تباه کوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(443, 'Genesis 18:24', 'Genesis', 18, 24, '&nbsp;کۀ په ښار کښې پنځوس صادقان کسان وى، نو تۀ به ټول ښار تباه کوې څۀ؟ تۀ به دوئ نۀ معاف کوې د دې دپاره چې هغه پنځوس کسان بچ شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(444, 'Genesis 18:25', 'Genesis', 18, 25, '&nbsp;دا څنګه کېدے شى چې تۀ به صادقان د بدعملو سره ووژنې؟ دا خو ناممکنه ده، تۀ داسې نۀ کوې. کۀ تۀ داسې وکړې، نو صادقانو خلقو ته به د بدعملو سره يو شان سزا مِلاو شى. دا ستا دپاره ناممکنه ده. ځکه د دُنيا اِنصاف کوونکے به خامخا اِنصاف کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(445, 'Genesis 18:26', 'Genesis', 18, 26, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”کۀ په سدوم کښې پنځوس صادقان کسان هم وى، نو زۀ به د هغوئ په خاطر ټول ښار بچ کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(446, 'Genesis 18:27', 'Genesis', 18, 27, '&nbsp;اِبراهيم بيا وفرمائيل، ”مالِکه خُدايه، ما معاف کړه چې زۀ زړَور شوم او ستا په مخکښې خبرې کوم. ځکه چې زۀ ستا په مخکښې هيڅ هم نۀ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(447, 'Genesis 18:28', 'Genesis', 18, 28, '&nbsp;خو کېدے شى چې هلته د پنځوسو صادقانو په ځائ صِرف پينځۀ څلوېښت وى. نو تۀ به د پينځو کسانو د کمى په وجه ټول ښار تباه کوې څۀ؟“ مالِک خُدائ جواب ورکړو، ”کۀ پينځۀ څلوېښت صادقان هم وى نو زۀ به هغه ښار نۀ تباه کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(448, 'Genesis 18:29', 'Genesis', 18, 29, '&nbsp;اِبراهيم بيا وفرمائيل، ”کېدے شى چې هلته صِرف څلوېښت کسان وى.“ هغۀ جواب ورکړو چې، ”کۀ څلوېښت کسان هم وى نو زۀ به هغه ښار نۀ تباه کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(449, 'Genesis 18:30', 'Genesis', 18, 30, '&nbsp;اِبراهيم وفرمائيل، ”مالِکه خُدايه، غصه کېږه مه، خو زۀ يو ځل بيا عرض کوم. کۀ هلته صِرف دېرش کسان وى نو بيا؟“ هغۀ وفرمائيل، ”زۀ به داسې نۀ کوم کۀ دېرش هم وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(450, 'Genesis 18:31', 'Genesis', 18, 31, '&nbsp;اِبراهيم وفرمائيل، ”مالِکه خُدايه، ما معاف کړه چې زۀ زړَور شوم او ستا په مخکښې خبرې کوم، خو کۀ صِرف شل کسان وى؟“ هغۀ وفرمائيل، ”زۀ به هغه ښار نۀ تباه کوم کۀ شل کسان هم وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(451, 'Genesis 18:32', 'Genesis', 18, 32, '&nbsp;اِبراهيم وفرمائيل، ”مالِکه خُدايه، غصه کېږه مه، زۀ به صِرف يو ځل بيا عرض کوم. کۀ هلته صِرف لس کسان وى نو بيا؟“ هغۀ وفرمائيل، ”کۀ لس کسان هم وى نو زۀ به هغه ښار نۀ تباه کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(452, 'Genesis 18:33', 'Genesis', 18, 33, '&nbsp;چې د اِبراهيم سره يې خبرې ختمې کړې نو مالِک خُدائ لاړو او اِبراهيم کور ته راوګرځېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(453, 'Genesis 19:1', 'Genesis', 19, 1, '&nbsp;په هغه ماښام چې دوه فرښتې سدوم ته راغلې، لوط د ښار د دروازې سره نزدې د جرګې په ځائ کښې ناست وو. چې څنګه هغۀ هغوئ وليدې، نو هغه پاڅېدو او ستړې مشى له ورَغلو. هغه هغوئ ته د عزت نه ټيټ شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(454, 'Genesis 19:2', 'Genesis', 19, 2, '&nbsp;او وې فرمائيل، ”صاحِبانو، زۀ به ستاسو خِدمت کوم. ما سره کور ته لاړ شئ. تاسو پښې ووينځئ او شپې ته ايسار شئ. تاسو چې سحر وختى پاڅئ نو په خپله مخه تلے شئ.“ خو هغوئ جواب ورکړو، ”نه، مونږ به دلته د جرګې په ځائ کښې شپه وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(455, 'Genesis 19:3', 'Genesis', 19, 3, '&nbsp;خو هغۀ ډېر زور کولو او آخر ورسره کور ته لاړل. لوط خپلو نوکرانو له حُکم ورکړو چې روټۍ پخه کړى او د مېلمنو دپاره ښۀ خوراک تيار کړى. چې روټۍ تياره شوه، نو هغوئ وخوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(456, 'Genesis 19:4', 'Genesis', 19, 4, '&nbsp;د مېلمنو د څملاستو نه مخکښې، د سدوم خلق د هغه کور نه تاو شول، چې د ښار ټول خلق، واړۀ زاړۀ په کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
