(470, 'Genesis 19:18', 'Genesis', 19, 18, '&nbsp;خو لوط جواب ورکړو، ”اُف، نه صاحِبانو، په مونږ داسې مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(471, 'Genesis 19:19', 'Genesis', 19, 19, '&nbsp;تاسو زما سره ډېر ښۀ کړى دى او زما ژوند مو بچ کړو. خو غرونه ډېر زيات لرې دى، تباهى به زما په سر راشى او هلته رسېدو نه مخکښې به زۀ مړ شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
