(473, 'Genesis 19:21', 'Genesis', 19, 21, '&nbsp;هغۀ جواب ورکړو، ”ټيک ده، زۀ به ستا خبره ومنم. زۀ به هغه ښار نۀ تباه کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
