(493, 'Genesis 20:3', 'Genesis', 20, 3, '&nbsp;خو يوه شپه هغۀ خُدائ پاک په خوب کښې وليدو چې ورته يې وفرمائيل، ”ګوره، تۀ د مرګ په خولۀ کښې ولاړ يې، ځکه چې کومه ښځه تا راوستې ده هغه وادۀ شوې هم ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(494, 'Genesis 20:4', 'Genesis', 20, 4, '&nbsp;خو ابى‌مَلِک ګوتې هم نۀ وې وروړې او هغۀ ووئيل، ”مالِکه خُدايه، زۀ بې‌ګناه يم. تۀ به ما او زما خلق تباه کوې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(495, 'Genesis 20:5', 'Genesis', 20, 5, '&nbsp;اِبراهيم خو په خپله فرمائيلى وُو چې هغه يې خور ده او هغې هم فرمائيلى وُو چې هغه يې ورور دے. ما خو دا په صفا نېت کړى دى او زما لاسونو ګناه نۀ ده کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(496, 'Genesis 20:6', 'Genesis', 20, 6, '&nbsp;خُدائ پاک په خوب کښې جواب ورکړو، ”آو، ما ته پته ده چې تا دا په صفا نېت کړى دى، هغې ته ګوتې وروړلو ته مې ځکه پرې نۀ ښودلې چې زما خِلاف ګناه ونۀ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(497, 'Genesis 20:7', 'Genesis', 20, 7, '&nbsp;خو اوس، هغه ښځه خپل خاوند ته واپس کړه. هغه يو نبى دے او هغه به درته دُعا وکړى او تۀ به مړ نۀ شې. خو کۀ تۀ هغه واپس نۀ ورکوې، نو زۀ تا خبروم چې تۀ او ستا ټول خلق به مړۀ کېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(498, 'Genesis 20:8', 'Genesis', 20, 8, '&nbsp;بل سحر وختى ابى‌مَلِک خپل ټول درباريان راوغوښتل او چې څۀ شوى وُو ورته يې ووئيل، او هغوئ سخت يرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(499, 'Genesis 20:9', 'Genesis', 20, 9, '&nbsp;بيا ابى‌مَلِک اِبراهيم راوغوښتلو او تپوس يې ترې وکړو، ”دا تا په مونږ څۀ کړى دى؟ ما تا سره څۀ بد کړى دى چې تا په ما او زما په بادشاهۍ دا افت راوستے دے؟ داسې خو د هيچا سره هم نۀ دى کول پکار، لکه چې تا زما سره کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(500, 'Genesis 20:10', 'Genesis', 20, 10, '&nbsp;دا تا ولې کړى دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');